import tensorcircuit as tc
import tensornetwork as tn

tc.set_backend('numpy')
backend=tc.backend

def _labels(n):
 return 'a','b',['c','d','e','f','g'][:n]

def apply_single(U, cur, axes):
 old,new,existing=_labels(len(axes))
 return np.einsum(new+old+','+old+''.join(existing)+'->'+new+''.join(existing), U, cur)

def apply_left(A, cur, axes):
 nb=len(axes); old,new,existing=_labels(nb); bond=chr(ord('h')+nb)
 return np.einsum(new+old+bond+','+old+''.join(existing)+'->'+new+''.join(existing)+bond, A, cur)

def apply_right(A, cur, axes):
 nb=len(axes); old,new,existing=_labels(nb); bond=chr(ord('h')+nb)
 return np.einsum(bond+new+old+','+old+''.join(existing)+'->'+new+''.join(existing)+bond, A, cur)

